export function lifecycleText(s={}){const date=v=>new Date(v).toLocaleString('ar-SA');if(s.deleting)return 'بدأ الحذف النهائي لهذا الكيان.';let text=s.trial?'تجربة مجانية حتى '+date(s.trial_ends_at):s.subscription_ends_at?'الاشتراك حتى '+date(s.subscription_ends_at):'الكيان مفعّل';if(s.read_only)text+=' · للاطلاع فقط؛ جدد الاشتراك لاستعادة الإضافة والدردشة.';if(s.delete_after)text+=' · الحذف النهائي لجميع الصور والبيانات: '+date(s.delete_after);else if(s.renewal_notice_due)text+=' · يبقى للاطلاع 6 أشهر بعد الانتهاء، ثم تُرسل رسالة تجديد ويُحذف بعد إرسالها بـ15 يومًا إن لم يُجدد.';return text}
export async function familyDashboard({rpc,element,button,busy,toast,showSection,maintenance=null}){
 const d=element('dialog',undefined,'family-dashboard'),head=element('header'),body=element('div');head.append(element('h2',maintenance?'لوحة صيانة العائلة':'لوحة إدارة العائلة'),button('إغلاق',()=>{d.close();d.remove()}));d.append(head,body);document.body.append(d);d.showModal();let version=0;const call=(action,payload={})=>rpc('family_admin',{action,payload:{...payload,...(maintenance?{maintenance}: {})}});
 async function load(){const n=++version;try{const data=await call('overview');if(n!==version||!d.open)return;body.replaceChildren();body.append(element('h3',data.family.name),element('p','الكود '+data.family.code),element('p',lifecycleText(data.lifecycle),'lifecycle-notice'));const metrics=element('div',undefined,'admin-metrics');for(const[key,label]of [['members','الأعضاء'],['pending','بانتظار الاعتماد'],['news','الأخبار'],['messages','الرسائل'],['maintenance','طلبات الصيانة']])metrics.append(element('article',data[key]+' '+label));body.append(metrics);
 if(!maintenance){const nav=element('nav',undefined,'admin-shortcuts');for(const[key,label]of [['members','إدارة الأعضاء والصلاحيات'],['review','مراجعة الأخبار'],['trash','الأخبار المخفية'],['announcements','الإعلانات'],['settings','العائلة والقرابة والتعريف'],['storage','المساحة والصيانة']])nav.append(button(label,async()=>{d.close();d.remove();await showSection(key)},'secondary'));nav.append(button('شجرة العائلة الكاملة والتصدير',()=>{d.close();d.remove();document.getElementById('whole-tree-open').click()},'secondary'));body.append(nav)}
 body.append(button('الأعضاء والإضافة اليدوية',()=>members(data.lifecycle.read_only),'primary'));const branding=element('form');branding.append(element('h3','هوية الكيان'));const name=element('input');name.value=data.family.name;name.required=true;name.maxLength=100;name.setAttribute('aria-label','اسم العائلة');const logo=element('input');logo.type='file';logo.accept='image/*';logo.setAttribute('aria-label','شعار العائلة');const save=element('button','حفظ الهوية','secondary');save.disabled=data.lifecycle.read_only;branding.append(name,logo,save);branding.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{const payload={name:name.value};if(logo.files[0])payload.logo=await logoData(logo.files[0]);await call('branding',payload);toast('حُفظت الهوية.');await load()})};body.append(branding);
 const settings=element('form');settings.append(element('h3','ضوابط النشر والدردشة'));const checks={};for(const[key,label]of [['chat_enabled','تشغيل الدردشة'],['public_chat_enabled','الدردشة العامة'],['private_chat_enabled','الخاص'],['restrict_gender_chat','منع الدردشة بين الجنسين'],['allow_groups','السماح بإنشاء مجموعات'],['journalist_approval','موافقة المدير على نشر الصحفي'],['auto_activate','التفعيل حسب أسماء العوائل'],['endorsements_enabled','نظام التعريف']]){const l=element('label',label,'inline'),i=element('input');i.type='checkbox';i.checked=!!data.settings[key];i.disabled=data.lifecycle.read_only;l.prepend(i);checks[key]=i;settings.append(l)}const ss=element('button','حفظ الضوابط','primary');ss.disabled=data.lifecycle.read_only;settings.append(ss);settings.onsubmit=e=>{e.preventDefault();return busy(ss,async()=>{await call('settings',{settings:Object.fromEntries(Object.entries(checks).map(([k,i])=>[k,i.checked]))});toast('حُفظت الضوابط.');await load()})};body.append(settings);
 if(maintenance)body.append(button('مراجعة ونشر الأخبار',()=>news(),'secondary'));
 const billing=element('section');billing.append(element('h3','اشتراك العائلة والفواتير'));for(const i of data.invoices||[])billing.append(element('p',i.plan_name+' · '+i.amount_sar+' ر.س · '+({issued:'بانتظار السداد',paid:'مسددة',void:'ملغاة'}[i.status]||i.status)));billing.append(element('p','لتجديد الاشتراك تواصل مع إدارة المنصة. لا توجد بوابة دفع إلكتروني مفعّلة.'));body.append(billing);const audit=element('details');audit.append(element('summary','سجل إجراءات الإدارة والصيانة'));for(const a of data.audit||[])audit.append(element('p',new Date(a.created_at).toLocaleString('ar-SA')+' · '+a.action+(a.maintenance_id?' · صيانة بتصريح':'')));body.append(audit)}catch(e){body.replaceChildren(element('p',e.message))}}
 async function members(readOnly){const data=await call('members');body.replaceChildren(button('العودة إلى لوحة الإدارة',load),element('h3','أفراد العائلة'));const search=element('input');search.placeholder='بحث بالاسم أو الجوال أو البريد';const list=element('div');body.append(search,list);function paint(){list.replaceChildren();for(const p of data.members.filter(p=>[p.display_name,p.phone,p.email].join(' ').includes(search.value))){const row=element('article',undefined,'member-admin-row');row.append(element('strong',p.display_name),element('p',(p.phone||'')+' · '+p.email));const role=element('select'),status=element('select');for(const[v,l]of [['member','عضو'],['journalist','صحفي'],['admin','مدير']]){const o=element('option',l);o.value=v;role.append(o)}for(const[v,l]of [['active','معتمد'],['pending','بانتظار الاعتماد'],['suspended','موقوف']]){const o=element('option',l);o.value=v;status.append(o)}role.value=p.role;status.value=p.status;role.disabled=status.disabled=readOnly||p.is_root;const save=button('حفظ',()=>busy(save,async()=>{await call('member_update',{id:p.id,role:role.value,status:status.value});toast('حُفظ العضو.')}),'secondary');save.disabled=readOnly||p.is_root;row.append(role,status,save);list.append(row)}}search.oninput=paint;paint();
 const f=element('form');f.append(element('h3','إضافة عضو يدويًا'),element('p','جهّز بيانات العضو وصلاحيته. يكمل التسجيل بالبريد نفسه ويؤكده قبل الدخول. لا يُنشأ له حساب بكلمة مرور مشتركة.'));const fields={};for(const[key,label,type]of [['full_name','الاسم الرباعي','text'],['email','البريد الإلكتروني','email'],['phone','الجوال الدولي أو 05xxxxxxxx','tel']]){const l=element('label',label),i=element('input');i.required=true;i.type=type;fields[key]=i;l.append(i);f.append(l)}for(const[key,label,opts]of [['gender','الجنس',[['male','ذكر'],['female','أنثى']]],['role','الصلاحية',[['member','عضو'],['journalist','صحفي'],['admin','مدير']]]]){const l=element('label',label),i=element('select');for(const[v,label]of opts){const o=element('option',label);o.value=v;i.append(o)}fields[key]=i;l.append(i);f.append(l)}const add=element('button','إضافة العضو','primary');add.disabled=readOnly;f.append(add);f.onsubmit=e=>{e.preventDefault();return busy(add,async()=>{await call('member_add',Object.fromEntries(Object.entries(fields).map(([k,i])=>[k,i.value.trim()])));toast('أضيف العضو؛ يكمل التسجيل وتأكيد البريد.');await members(readOnly)})};body.append(f,element('h3','أعضاء بانتظار إكمال التسجيل'));for(const p of data.prepared){const row=element('article');row.append(element('p',p.full_name+' · '+p.email),button('إلغاء الإضافة',()=>busy(null,async()=>{await call('member_cancel',{id:p.id});await members(readOnly)})));body.append(row)}}
 async function news(){const rows=await call('news');body.replaceChildren(button('العودة',load));for(const p of rows){const row=element('article');row.append(element('h3',p.title),element('p',p.body),button(p.published?'إلغاء النشر':'اعتماد ونشر',()=>busy(null,async()=>{await call('news_update',{id:p.id,published:!p.published});await news()})));body.append(row)}}
 await load();const timer=setInterval(()=>{if(!d.open||!d.isConnected)return clearInterval(timer);if(maintenance)call('overview').catch(e=>{body.replaceChildren(element('p',e.message));clearInterval(timer)})},15000);timer.unref?.();d.addEventListener('close',()=>{version++;clearInterval(timer);body.replaceChildren()});return d;
}
export async function logoData(file){if(file.size>20*1024*1024)throw Error('الشعار أكبر من 20 ميجابايت');const image=new Image(),url=URL.createObjectURL(file);try{image.src=url;await image.decode();const c=document.createElement('canvas'),s=Math.min(1,512/Math.max(image.naturalWidth,image.naturalHeight));c.width=Math.max(1,Math.round(image.naturalWidth*s));c.height=Math.max(1,Math.round(image.naturalHeight*s));const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(image,0,0,c.width,c.height);const data=c.toDataURL('image/jpeg',.72);if(data.length>280000)throw Error('اختر شعارًا أبسط');return data}finally{URL.revokeObjectURL(url)}}
